describe('Retry Button on Network Timeout', () => {
  beforeEach(() => {
    cy.visit('/api/data');
  });

  it('should display retry button when network request times out and allow retry', () => {
    // Intercept the initial API call and force it to fail with a timeout
    cy.intercept('GET', '/api/data', {
      forceNetworkError: true,
      delay: 1000
    }).as('initialRequest');

    // Trigger the API call
    cy.get('[data-testid="load-data-button"]').click();

    // Wait for the failed request
    cy.wait('@initialRequest');

    // Verify error message and retry button are displayed
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Network request timed out');
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Click the retry button
    cy.get('[data-testid="retry-button"]').click();

    // Intercept the retry request and make it succeed
    cy.intercept('GET', '/api/data', {
      statusCode: 200,
      body: { data: 'Successfully loaded data' }
    }).as('retryRequest');

    // Wait for the successful retry
    cy.wait('@retryRequest');

    // Verify data is loaded successfully
    cy.get('[data-testid="data-container"]').should('be.visible').should('contain', 'Successfully loaded data');
    cy.get('[data-testid="error-message"]').should('not.exist');
  });

  it('should disable retry button when request is in progress', () => {
    // Intercept the initial API call and make it take a long time
    cy.intercept('GET', '/api/data', {
      delay: 5000
    }).as('longRequest');

    // Trigger the API call
    cy.get('[data-testid="load-data-button"]').click();

    // Verify retry button is initially visible
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Wait for the request to start
    cy.wait('@longRequest', { timeout: 1000 });

    // Verify retry button is disabled while request is in progress
    cy.get('[data-testid="retry-button"]').should('be.disabled');

    // Verify loading indicator is visible
    cy.get('[data-testid="loading-indicator"]').should('be.visible');

    // Wait for the request to complete (or timeout)
    cy.wait('@longRequest', { timeout: 6000 });

    // Verify retry button is re-enabled after request finishes
    cy.get('[data-testid="retry-button"]').should('not.be.disabled');
  });
});
